// Packages:
// - ModelContextProtocol --version 1.*
// - Microsoft.Extensions.DependencyInjection
// - Microsoft.Extensions.Logging

using Microsoft.Extensions.Logging;
using ModelContextProtocol;
using ModelContextProtocol.Server;

// Sample model
public record Customer(string Id, string Name, string Tier, DateTime ActiveSince);

public interface ICustomerRepository
{
    Task<Customer?> GetByIdAsync(string id, CancellationToken ct);
}

public sealed class CustomerSummaryResource
{
    private readonly ICustomerRepository _customers;
    private readonly ILogger<CustomerSummaryResource> _logger;

    public CustomerSummaryResource(ICustomerRepository customers, ILogger<CustomerSummaryResource> logger)
    {
        _customers = customers;
        _logger = logger;
    }

    [McpServerResource(UriTemplate = "customer://{customerId}")]
    public async Task<string> GetAsync(
        string customerId,
        CancellationToken ct = default)
    {
        _logger.LogInformation("Fetching customer {CustomerId}", customerId);

        // Sample data: repository returns a Customer like this
        // Customer(Id: "CUST-2001", Name: "Contoso Inc.", Tier: "Enterprise", ActiveSince: 2023-01-15)
        var customer = await _customers.GetByIdAsync(customerId, ct);
        if (customer is null)
            throw new McpResourceNotFoundException($"Customer '{customerId}' not found.");

        var json = JsonSerializer.Serialize(new
        {
            customer.Id,
            customer.Name,
            customer.Tier,
            customer.ActiveSince
        });

        // Expected JSON output:
        // {
        //   "id": "CUST-2001",
        //   "name": "Contoso Inc.",
        //   "tier": "Enterprise",
        //   "activeSince": "2023-01-15T00:00:00"
        // }
        return json;
    }
}

